    Task DeleteShipmentAsync(int id);
}

using System.Net.Http.Json;
using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Client.Services;

public class ShipmentHttpService : IShipmentService
{
    private readonly HttpClient _http;

    public ShipmentHttpService(HttpClient http)
    {
        _http = http;
    }

    public async Task<List<Shipment>> GetShipmentsAsync(string? statusFilter = null, string? searchTerm = null)
    {
        var query = new List<string>();
        if (!string.IsNullOrEmpty(statusFilter))
            query.Add($"status={Uri.EscapeDataString(statusFilter)}");
        if (!string.IsNullOrEmpty(searchTerm))
            query.Add($"search={Uri.EscapeDataString(searchTerm)}");

        var url = "/api/shipments";
        if (query.Count > 0)
            url += "?" + string.Join("&", query);

        return await _http.GetFromJsonAsync<List<Shipment>>(url) ?? new();
    }

    public async Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        try
        {
            return await _http.GetFromJsonAsync<Shipment>($"/api/shipments/track/{Uri.EscapeDataString(trackingNumber)}");
        }
        catch (HttpRequestException ex) when (ex.StatusCode == System.Net.HttpStatusCode.NotFound)
        {
            return null;
        }
    }

    public async Task<Shipment?> GetShipmentByIdAsync(int id)
    {
        try
        {
            return await _http.GetFromJsonAsync<Shipment>($"/api/shipments/{id}");
        }
        catch (HttpRequestException ex) when (ex.StatusCode == System.Net.HttpStatusCode.NotFound)
        {
            return null;
        }
    }

    public async Task<Shipment> CreateShipmentAsync(Shipment shipment)
    {
        var response = await _http.PostAsJsonAsync("/api/shipments", shipment);
        response.EnsureSuccessStatusCode();
        return (await response.Content.ReadFromJsonAsync<Shipment>())!;
    }

    public async Task<Shipment> UpdateShipmentAsync(Shipment shipment)
    {
        var response = await _http.PutAsJsonAsync($"/api/shipments/{shipment.Id}", shipment);
        response.EnsureSuccessStatusCode();
        return (await response.Content.ReadFromJsonAsync<Shipment>())!;
    }

    public async Task DeleteShipmentAsync(int id)
    {
        var response = await _http.DeleteAsync($"/api/shipments/{id}");
        response.EnsureSuccessStatusCode();
    }
}

using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

public class ShipmentService : IShipmentService
{
    private readonly ApplicationDbContext _db;

    public ShipmentService(ApplicationDbContext db)
    {
        _db = db;
    }

    public async Task<List<Shipment>> GetShipmentsAsync(string? statusFilter = null, string? searchTerm = null)
    {
        var query = _db.Shipments.AsQueryable();

        if (!string.IsNullOrEmpty(statusFilter) && Enum.TryParse<ShipmentStatus>(statusFilter, true, out var status))
        {
            query = query.Where(s => s.Status == status);
        }

        if (!string.IsNullOrEmpty(searchTerm))
        {
            var term = searchTerm.ToLower();
            query = query.Where(s =>
                s.TrackingNumber.ToLower().Contains(term) ||
                s.Origin.ToLower().Contains(term) ||
                s.Destination.ToLower().Contains(term) ||
                s.RecipientName.ToLower().Contains(term));
        }

        return await query.OrderByDescending(s => s.CreatedDate).ToListAsync();
    }

    public async Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        return await _db.Shipments.FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
    }

    public async Task<Shipment?> GetShipmentByIdAsync(int id)
    {
        return await _db.Shipments.FindAsync(id);
    }

    public async Task<Shipment> CreateShipmentAsync(Shipment shipment)
    {
        shipment.CreatedDate = DateTime.UtcNow;
        if (string.IsNullOrEmpty(shipment.TrackingNumber))
        {
            shipment.TrackingNumber = $"TRK-{DateTime.UtcNow:yyyy}-{Random.Shared.Next(1000, 9999)}";
        }
        _db.Shipments.Add(shipment);
        await _db.SaveChangesAsync();
        return shipment;
    }

    public async Task<Shipment> UpdateShipmentAsync(Shipment shipment)
    {
        _db.Shipments.Update(shipment);
        await _db.SaveChangesAsync();
        return shipment;
    }

    public async Task DeleteShipmentAsync(int id)
    {
        var shipment = await _db.Shipments.FindAsync(id);
        if (shipment is not null)
        {
            _db.Shipments.Remove(shipment);
            await _db.SaveChangesAsync();
        }
    }
}

