@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize]
@inject IShipmentService ShipmentService
@inject NavigationManager Nav

<PageTitle>Shipments</PageTitle>

<h2>Shipments</h2>

<div class="row mb-3">
    <div class="col-md-3">
        <select class="form-select" @bind="statusFilter" @bind:after="LoadShipments">
            <option value="">All Statuses</option>
            @foreach (var s in Enum.GetValues<ShipmentStatus>())
            {
                <option value="@s">@s</option>
            }
        </select>
    </div>
    <div class="col-md-4">
        <input type="text" class="form-control" placeholder="Search tracking #, origin, destination, recipient..."
               @bind="searchTerm" @bind:event="oninput" @bind:after="LoadShipments" />
    </div>
    <div class="col-md-3 ms-auto text-end">
        <button class="btn btn-primary" @onclick="() => showNewForm = !showNewForm">
            @(showNewForm ? "Cancel" : "New Shipment")
        </button>
    </div>
</div>

@if (showNewForm)
{
    <div class="card mb-4">
        <div class="card-body">
            <h5 class="card-title">Create New Shipment</h5>
            <div class="row g-3">
                <div class="col-md-6">
                    <label class="form-label">Origin</label>
                    <input class="form-control" @bind="newShipment.Origin" />
                </div>
                <div class="col-md-6">
                    <label class="form-label">Destination</label>
                    <input class="form-control" @bind="newShipment.Destination" />
                </div>
                <div class="col-md-4">
                    <label class="form-label">Recipient Name</label>
                    <input class="form-control" @bind="newShipment.RecipientName" />
                </div>
                <div class="col-md-4">
                    <label class="form-label">Sender Name</label>
                    <input class="form-control" @bind="newShipment.SenderName" />
                </div>
                <div class="col-md-2">
                    <label class="form-label">Weight (kg)</label>
                    <input type="number" step="0.1" class="form-control" @bind="newShipment.WeightKg" />
                </div>
                <div class="col-md-2">
                    <label class="form-label">Est. Delivery</label>
                    <input type="date" class="form-control" @bind="newShipment.EstimatedDelivery" />
                </div>
                <div class="col-12">
                    <label class="form-label">Notes</label>
                    <textarea class="form-control" @bind="newShipment.Notes"></textarea>
                </div>
                <div class="col-12">
                    <button class="btn btn-success" @onclick="CreateShipment">Create Shipment</button>
                </div>
            </div>
        </div>
    </div>
}

@if (shipments is null)
{
    <p><em>Loading...</em></p>
}
else if (shipments.Count == 0)
{
    <p>No shipments found.</p>
}
else
{
    <table class="table table-hover">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Origin</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Est. Delivery</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var s in shipments)
            {
                <tr style="cursor:pointer" @onclick="() => Nav.NavigateTo($&quot;/shipments/{s.Id}&quot;)">
                    <td><strong>@s.TrackingNumber</strong></td>
                    <td>@s.Origin</td>
                    <td>@s.Destination</td>
                    <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
                    <td>@s.EstimatedDelivery?.ToString("MMM dd, yyyy")</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<Shipment>? shipments;
    private string statusFilter = "";
    private string searchTerm = "";
    private bool showNewForm;
    private Shipment newShipment = new();

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        shipments = await ShipmentService.GetShipmentsAsync(
            string.IsNullOrEmpty(statusFilter) ? null : statusFilter,
            string.IsNullOrEmpty(searchTerm) ? null : searchTerm);
    }

    private async Task CreateShipment()
    {
        await ShipmentService.CreateShipmentAsync(newShipment);
        newShipment = new();
        showNewForm = false;
        await LoadShipments();
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-warning text-dark",
        ShipmentStatus.PickedUp => "bg-info text-dark",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-info",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Exception => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/shipments/{Id:int}"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize]
@inject IShipmentService ShipmentService
@inject NavigationManager Nav

<PageTitle>Shipment Detail</PageTitle>

@if (shipment is null)
{
    <p><em>Loading...</em></p>
}
else
{
    <h2>Shipment @shipment.TrackingNumber</h2>

    <div class="mb-3">
        <button class="btn btn-outline-secondary" @onclick="GoBack">← Back to List</button>
    </div>

    <div class="row g-3">
        <div class="col-md-6">
            <label class="form-label">Tracking Number</label>
            <input class="form-control" @bind="shipment.TrackingNumber" readonly />
        </div>
        <div class="col-md-6">
            <label class="form-label">Status</label>
            <select class="form-select" @bind="shipment.Status">
                @foreach (var s in Enum.GetValues<ShipmentStatus>())
                {
                    <option value="@s">@s</option>
                }
            </select>
        </div>
        <div class="col-md-6">
            <label class="form-label">Origin</label>
            <input class="form-control" @bind="shipment.Origin" />
        </div>
        <div class="col-md-6">
            <label class="form-label">Destination</label>
            <input class="form-control" @bind="shipment.Destination" />
        </div>
        <div class="col-md-6">
            <label class="form-label">Sender Name</label>
            <input class="form-control" @bind="shipment.SenderName" />
        </div>
        <div class="col-md-6">
            <label class="form-label">Recipient Name</label>
            <input class="form-control" @bind="shipment.RecipientName" />
        </div>
        <div class="col-md-4">
            <label class="form-label">Weight (kg)</label>
            <input type="number" step="0.1" class="form-control" @bind="shipment.WeightKg" />
        </div>
        <div class="col-md-4">
            <label class="form-label">Estimated Delivery</label>
            <input type="date" class="form-control" @bind="shipment.EstimatedDelivery" />
        </div>
        <div class="col-md-4">
            <label class="form-label">Actual Delivery</label>
            <input type="date" class="form-control" @bind="shipment.ActualDelivery" />
        </div>
        <div class="col-md-6">
            <label class="form-label">Created Date</label>
            <input class="form-control" value="@shipment.CreatedDate.ToString("g")" readonly />
        </div>
        <div class="col-12">
            <label class="form-label">Notes</label>
            <textarea class="form-control" @bind="shipment.Notes"></textarea>
        </div>
        <div class="col-12">
            <button class="btn btn-primary me-2" @onclick="Save">Save</button>
            <button class="btn btn-danger" @onclick="ConfirmDelete">Delete</button>
        </div>
    </div>

    @if (showDeleteConfirm)
    {
        <div class="alert alert-danger mt-3">
            <p>Are you sure you want to delete this shipment?</p>
            <button class="btn btn-danger me-2" @onclick="Delete">Yes, Delete</button>
            <button class="btn btn-secondary" @onclick="() => showDeleteConfirm = false">Cancel</button>
        </div>
    }

    @if (!string.IsNullOrEmpty(message))
    {
        <div class="alert alert-info mt-3">@message</div>
    }
}

@code {
    [Parameter] public int Id { get; set; }

    private Shipment? shipment;
    private bool showDeleteConfirm;
    private string? message;

    protected override async Task OnInitializedAsync()
    {
        shipment = await ShipmentService.GetShipmentByIdAsync(Id);
    }

    private async Task Save()
    {
        if (shipment is not null)
        {
            await ShipmentService.UpdateShipmentAsync(shipment);
            message = "Shipment saved successfully.";
        }
    }

    private void ConfirmDelete()
    {
        showDeleteConfirm = true;
    }

    private async Task Delete()
    {
        if (shipment is not null)
        {
            await ShipmentService.DeleteShipmentAsync(shipment.Id);
            Nav.NavigateTo("/shipments");
        }
    }

    private void GoBack()
    {
        Nav.NavigateTo("/shipments");
    }
}

@page "/track"
@page "/track/{TrackingNumber}"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<h2>Track Your Shipment</h2>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number (e.g. TRK-2026-1001)"
                   @bind="searchTrackingNumber" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="SearchShipment">Track</button>
        </div>
    </div>
</div>

@if (searched && shipment is null)
{
    <div class="alert alert-warning">
        <h5>Shipment Not Found</h5>
        <p>We couldn't find a shipment with tracking number <strong>@displayedTrackingNumber</strong>. Please check the number and try again.</p>
    </div>
}

@if (shipment is not null)
{
    <div class="card mb-4">
        <div class="card-body">
            <h3 class="card-title">📦 @shipment.TrackingNumber</h3>
            <div class="row mt-3">
                <div class="col-md-6">
                    <p><strong>From:</strong> @shipment.Origin</p>
                    <p><strong>To:</strong> @shipment.Destination</p>
                    <p><strong>Recipient:</strong> @shipment.RecipientName</p>
                </div>
                <div class="col-md-6">
                    <p><strong>Status:</strong> <span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">@GetStatusDescription(shipment.Status)</span></p>
                    <p><strong>Estimated Delivery:</strong> @(shipment.EstimatedDelivery?.ToString("MMMM dd, yyyy") ?? "N/A")</p>
                    @if (shipment.ActualDelivery.HasValue)
                    {
                        <p><strong>Delivered:</strong> @shipment.ActualDelivery.Value.ToString("MMMM dd, yyyy")</p>
                    }
                </div>
            </div>
        </div>
    </div>

    <div class="card">
        <div class="card-body">
            <h5 class="card-title">Shipment Progress</h5>
            <div class="d-flex justify-content-between align-items-center mt-4 mb-2 position-relative">
                @{
                    var steps = new[] {
                        ShipmentStatus.Pending,
                        ShipmentStatus.PickedUp,
                        ShipmentStatus.InTransit,
                        ShipmentStatus.OutForDelivery,
                        ShipmentStatus.Delivered
                    };
                    var currentIndex = shipment.Status == ShipmentStatus.Exception
                        ? -1
                        : Array.IndexOf(steps, shipment.Status);
                }

                <div class="progress w-100 position-absolute" style="height: 4px; z-index: 0; left: 0; right: 0;">
                    <div class="progress-bar @(shipment.Status == ShipmentStatus.Exception ? "bg-danger" : "bg-success")"
                         style="width: @(currentIndex >= 0 ? (currentIndex * 25) : 0)%"></div>
                </div>

                @for (int i = 0; i < steps.Length; i++)
                {
                    var step = steps[i];
                    var isActive = i <= currentIndex;
                    var isCurrent = i == currentIndex;
                    <div class="text-center position-relative" style="z-index: 1; flex: 1;">
                        <div class="rounded-circle d-inline-flex align-items-center justify-content-center @(isActive ? "bg-success text-white" : "bg-light text-muted border")"
                             style="width: 36px; height: 36px; @(isCurrent ? "box-shadow: 0 0 0 3px rgba(25,135,84,.4);" : "")">
                            @if (isActive)
                            {
                                <span>✓</span>
                            }
                            else
                            {
                                <span>@(i + 1)</span>
                            }
                        </div>
                        <div class="small mt-1 @(isActive ? "fw-bold" : "text-muted")">@step</div>
                    </div>
                }
            </div>

            @if (shipment.Status == ShipmentStatus.Exception)
            {
                <div class="alert alert-danger mt-3">
                    <strong>⚠️ Exception:</strong> There is an issue with this shipment.
                    @if (!string.IsNullOrEmpty(shipment.Notes))
                    {
                        <br /><span>@shipment.Notes</span>
                    }
                </div>
            }
        </div>
    </div>
}

@code {
    [Parameter] public string? TrackingNumber { get; set; }

    private string searchTrackingNumber = "";
    private string? displayedTrackingNumber;
    private Shipment? shipment;
    private bool searched;

    protected override async Task OnInitializedAsync()
    {
        if (!string.IsNullOrEmpty(TrackingNumber))
        {
            searchTrackingNumber = TrackingNumber;
            await SearchShipment();
        }
    }

    private async Task SearchShipment()
    {
        if (string.IsNullOrWhiteSpace(searchTrackingNumber))
            return;

        displayedTrackingNumber = searchTrackingNumber.Trim();
        shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(displayedTrackingNumber);
        searched = true;
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await SearchShipment();
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-warning text-dark",
        ShipmentStatus.PickedUp => "bg-info text-dark",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-info",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Exception => "bg-danger",
        _ => "bg-secondary"
    };

    private static string GetStatusDescription(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "Pending - Awaiting pickup",
        ShipmentStatus.PickedUp => "Picked Up - In carrier possession",
        ShipmentStatus.InTransit => "In Transit - On the way",
        ShipmentStatus.OutForDelivery => "Out for Delivery - Arriving today",
        ShipmentStatus.Delivered => "Delivered",
        ShipmentStatus.Exception => "Exception - Issue encountered",
        _ => status.ToString()
    };
}

