 @page "/"
 @using ShipmentTracker.Client.Models
 @using ShipmentTracker.Client.Services
 @attribute [Authorize]
 @inject IShipmentService ShipmentService
 @inject NavigationManager Nav

 <PageTitle>Dashboard</PageTitle>

 <h2>Shipment Dashboard</h2>

 @if (shipments is null)
 {
     <p><em>Loading dashboard...</em></p>
 }
 else
 {
     <div class="row mb-4">
         <div class="col-md-3">
             <div class="card text-bg-primary mb-3">
                 <div class="card-body">
                     <h5 class="card-title">Total Shipments</h5>
                     <p class="card-text display-6">@shipments.Count</p>
                 </div>
             </div>
         </div>
         <div class="col-md-3">
             <div class="card text-bg-info mb-3">
                 <div class="card-body">
                     <h5 class="card-title">In Transit</h5>
                     <p class="card-text display-6">@shipments.Count(s => s.Status == ShipmentStatus.InTransit)</p>
                 </div>
             </div>
         </div>
         <div class="col-md-3">
             <div class="card text-bg-success mb-3">
                 <div class="card-body">
                     <h5 class="card-title">Delivered</h5>
                     <p class="card-text display-6">@shipments.Count(s => s.Status == ShipmentStatus.Delivered)</p>
                 </div>
             </div>
         </div>
         <div class="col-md-3">
             <div class="card text-bg-danger mb-3">
                 <div class="card-body">
                     <h5 class="card-title">Exceptions</h5>
                     <p class="card-text display-6">@shipments.Count(s => s.Status == ShipmentStatus.Exception)</p>
                 </div>
             </div>
         </div>
     </div>
 }

 <div class="card">
     <div class="card-body">
         <h5 class="card-title">Quick Track</h5>
         <p class="card-text">Enter a tracking number to look up a shipment.</p>
         <div class="input-group" style="max-width: 500px;">
             <input type="text" class="form-control" placeholder="e.g. TRK-2026-1001" @bind="trackingNumber" @onkeydown="HandleKeyDown" />
             <button class="btn btn-primary" @onclick="TrackShipment">Track</button>
         </div>
     </div>
 </div>

 @code {
     private List<Shipment>? shipments;
     private string trackingNumber = "";

     protected override async Task OnInitializedAsync()
     {
         shipments = await ShipmentService.GetShipmentsAsync();
     }

     private void TrackShipment()
     {
         if (!string.IsNullOrWhiteSpace(trackingNumber))
             Nav.NavigateTo($"/track/{Uri.EscapeDataString(trackingNumber.Trim())}");
     }

     private void HandleKeyDown(KeyboardEventArgs e)
     {
         if (e.Key == "Enter")
             TrackShipment();
     }
 }

