 @page "/shipments/{Id:int}"
 @using ShipmentTracker.Client.Models
 @using ShipmentTracker.Client.Services
 @attribute [Authorize]
 @inject IShipmentService ShipmentService
 @inject NavigationManager Nav

 <PageTitle>Shipment Detail</PageTitle>

 @if (shipment is null)
 {
     <p><em>Loading...</em></p>
 }
 else
 {
     <h2>Shipment @shipment.TrackingNumber</h2>

     <div class="mb-3">
         <button class="btn btn-outline-secondary" @onclick="GoBack">← Back to List</button>
     </div>

     <div class="row g-3">
         <div class="col-md-6">
             <label class="form-label">Tracking Number</label>
             <input class="form-control" @bind="shipment.TrackingNumber" readonly />
         </div>
         <div class="col-md-6">
             <label class="form-label">Status</label>
             <select class="form-select" @bind="shipment.Status">
                 @foreach (var s in Enum.GetValues<ShipmentStatus>())
                 {
                     <option value="@s">@s</option>
                 }
             </select>
         </div>
         <div class="col-md-6">
             <label class="form-label">Origin</label>
             <input class="form-control" @bind="shipment.Origin" />
         </div>
         <div class="col-md-6">
             <label class="form-label">Destination</label>
             <input class="form-control" @bind="shipment.Destination" />
         </div>
         <div class="col-md-6">
             <label class="form-label">Sender Name</label>
             <input class="form-control" @bind="shipment.SenderName" />
         </div>
         <div class="col-md-6">
             <label class="form-label">Recipient Name</label>
             <input class="form-control" @bind="shipment.RecipientName" />
         </div>
         <div class="col-md-4">
             <label class="form-label">Weight (kg)</label>
             <input type="number" step="0.1" class="form-control" @bind="shipment.WeightKg" />
         </div>
         <div class="col-md-4">
             <label class="form-label">Estimated Delivery</label>
             <input type="date" class="form-control" @bind="shipment.EstimatedDelivery" />
         </div>
         <div class="col-md-4">
             <label class="form-label">Actual Delivery</label>
             <input type="date" class="form-control" @bind="shipment.ActualDelivery" />
         </div>
         <div class="col-md-6">
             <label class="form-label">Created Date</label>
             <input class="form-control" value="@shipment.CreatedDate.ToString("g")" readonly />
         </div>
         <div class="col-12">
             <label class="form-label">Notes</label>
             <textarea class="form-control" @bind="shipment.Notes"></textarea>
         </div>
         <div class="col-12">
             <button class="btn btn-primary me-2" @onclick="Save">Save</button>
             <button class="btn btn-danger" @onclick="ConfirmDelete">Delete</button>
         </div>
     </div>

     @if (showDeleteConfirm)
     {
         <div class="alert alert-danger mt-3">
             <p>Are you sure you want to delete this shipment?</p>
             <button class="btn btn-danger me-2" @onclick="Delete">Yes, Delete</button>
             <button class="btn btn-secondary" @onclick="() => showDeleteConfirm = false">Cancel</button>
         </div>
     }

     @if (!string.IsNullOrEmpty(message))
     {
         <div class="alert alert-info mt-3">@message</div>
     }
 }

 @code {
     [Parameter] public int Id { get; set; }

     private Shipment? shipment;
     private bool showDeleteConfirm;
     private string? message;

     protected override async Task OnInitializedAsync()
     {
         shipment = await ShipmentService.GetShipmentByIdAsync(Id);
     }

     private async Task Save()
     {
         if (shipment is not null)
         {
             await ShipmentService.UpdateShipmentAsync(shipment);
             message = "Shipment saved successfully.";
         }
     }

     private void ConfirmDelete()
     {
         showDeleteConfirm = true;
     }

     private async Task Delete()
     {
         if (shipment is not null)
         {
             await ShipmentService.DeleteShipmentAsync(shipment.Id);
             Nav.NavigateTo("/shipments");
         }
     }

     private void GoBack()
     {
         Nav.NavigateTo("/shipments");
     }
 }

